import { useState } from "react";

const IMAGE_DATA = "data:image/jpeg;base64,";

export default function FiveWhysFamilies() {
  const [step, setStep] = useState(-1); // -1 = intro amb foto, 0-4 = preguntes amb esquema, 5 = final amb foto
  const [answers, setAnswers] = useState([]);
  const [currentAnswer, setCurrentAnswer] = useState("");
  const [selectedChair, setSelectedChair] = useState(null);

  const questions = [
    "Per què les famílies no venen a les reunions d'inici de curs?",
    "I per què passa això?",
    "Però per què exactament?",
    "I això, per què?",
    "Última vegada... per què?",
  ];

  const suggestions = [
    [
      "Perquè moltes no poden assistir en l’horari establert.",
      "Perquè estan desconnectades de la cultura de centre.",
    ],
    [
      "Perquè coincideix amb horaris laborals o responsabilitats familiars.",
      "Perquè socioculturalment es senten desvinculats de l’educació dels seus fills.",
    ],
    [
      "Perquè el centre només dóna una opció d’horari",
      "Perquè tenen altres prioritats més enllà de l’educació.",
    ],
    [
      "Perquè es prioritza la facilitat d’organitzar el professorat",
      "Perquè ningú els ha explicat les possibilitats que els obre la educació.",
    ],
    [
      "Perquè les famílies no eren a la presa de decisions de l'horari. Per tant, no s’han tingut en compte les seves necessitats ni s’ha recollit informació sobre la disponibilitat real de les famílies.",
      "Perquè no s'ha pensat en que poden existir aquestes famílies ni s'han tingut en compte les seves necessitats. I no s’ha fet ús dels recursos TIS i treballadors socials que els hagués informat de la importància d’assistir a les reunions d’inici de curs.",
    ],
  ];

  const showFinal = step === 5;
  const inIntro = step === -1;
  const inQuestion = step >= 0 && step <= 4;

  const totalChairs = 20;
  const filledPerStep = [0, 5, 9, 13, 17, 20];
  const currentFilled = inQuestion ? filledPerStep[step] : showFinal ? 20 : 0;

  const handleStart = () => setStep(0);

  const handleSubmit = () => {
    if (!currentAnswer.trim()) return;
    const newAnswers = [...answers, currentAnswer.trim()];
    setAnswers(newAnswers);
    setCurrentAnswer("");
    setSelectedChair(null);
    if (step === 4) setStep(5);
    else setStep(step + 1);
  };

  const handleSuggestion = (text) => setCurrentAnswer(text);

  const reset = () => {
    setStep(-1);
    setAnswers([]);
    setCurrentAnswer("");
    setSelectedChair(null);
  };

  const palette = {
    bg: "#1a1f26",
    bgSoft: "#252b33",
    panel: "#eae3d2",
    panelDark: "#c9bfa5",
    ink: "#1a1f26",
    inkSoft: "#4a5260",
    accent: "#8b2f2f",
    accentDark: "#5a1f1f",
    wood: "#8b6f47",
    curtain: "#3d4a3a",
    chalk: "#d4c9a8",
    muted: "#7a8291",
  };

  const chairs = Array.from({ length: totalChairs }, (_, i) => ({
    id: i,
    row: Math.floor(i / 5),
    col: i % 5,
  }));
  const occupancyOrder = [
    2, 7, 12, 0, 5, 10, 3, 8, 13, 1, 6, 11, 4, 9, 14, 15, 17, 16, 18, 19,
  ];
  const occupiedChairs = new Set(occupancyOrder.slice(0, currentFilled));

  return (
    <div
      style={{
        minHeight: "100vh",
        background: palette.bg,
        fontFamily: "'Libre Caslon Text', Georgia, 'Times New Roman', serif",
        color: palette.panel,
        padding: "0",
        position: "relative",
      }}
    >
      <div
        style={{
          background: palette.bgSoft,
          borderBottom: `1px solid ${palette.muted}33`,
          padding: "14px 24px",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          fontFamily: "'Courier New', monospace",
          fontSize: "10px",
          letterSpacing: "3px",
          color: palette.muted,
        }}
      >
        <span>CENTRE EDUCATIU · DIAGNÒSTIC INTERN</span>
        <span>DOSSIER N.º 5W–01</span>
      </div>

      <div style={{ maxWidth: "1000px", margin: "0 auto", padding: "40px 24px 60px" }}>
        {/* INTRO AMB FOTO */}
        {inIntro && (
          <div style={{ animation: "fadeIn 0.8s ease" }}>
            <div
              style={{
                position: "relative",
                marginBottom: "40px",
                border: `1px solid ${palette.muted}44`,
                boxShadow: "0 20px 60px rgba(0,0,0,0.5)",
              }}
            >
              <img
                src={IMAGE_DATA}
                alt="Una sala d'actes amb cadires buides, una mestra sola i dos ocells directius"
                style={{
                  width: "100%",
                  display: "block",
                  filter: "contrast(1.05) saturate(0.95)",
                }}
              />
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background:
                    "radial-gradient(ellipse at center, transparent 40%, rgba(26, 31, 38, 0.3) 100%)",
                  pointerEvents: "none",
                }}
              />
              <div
                style={{
                  position: "absolute",
                  bottom: "16px",
                  left: "16px",
                  background: "rgba(26, 31, 38, 0.85)",
                  backdropFilter: "blur(4px)",
                  padding: "8px 14px",
                  fontFamily: "'Courier New', monospace",
                  fontSize: "10px",
                  letterSpacing: "2px",
                  color: palette.chalk,
                  border: `1px solid ${palette.muted}66`,
                }}
              >
                EXP. FOTOGRÀFIC · 17:32 · SETEMBRE
              </div>
            </div>

            <div style={{ textAlign: "center", maxWidth: "640px", margin: "0 auto" }}>
              <div
                style={{
                  fontFamily: "'Courier New', monospace",
                  fontSize: "11px",
                  letterSpacing: "5px",
                  color: palette.accent,
                  marginBottom: "16px",
                }}
              >
                MÈTODE DELS 5 PERQUÈS
              </div>
              <h1
                style={{
                  fontSize: "clamp(30px, 5vw, 48px)",
                  fontStyle: "italic",
                  lineHeight: 1.15,
                  margin: "0 0 24px",
                  color: palette.panel,
                  fontWeight: 400,
                }}
              >
                Les famílies no venen a les<br />
                reunions d'inici de curs.
              </h1>
              <div
                style={{
                  fontSize: "16px",
                  lineHeight: 1.6,
                  color: palette.chalk,
                  marginBottom: "36px",
                  fontStyle: "italic",
                }}
              >
                Una docent. Dues autoritats. Quaranta cadires buides.<br />
                Anem a investigar per què.
              </div>
              <button
                onClick={handleStart}
                style={{
                  background: palette.accent,
                  color: palette.panel,
                  border: "none",
                  padding: "16px 36px",
                  fontSize: "12px",
                  fontFamily: "'Courier New', monospace",
                  letterSpacing: "4px",
                  textTransform: "uppercase",
                  cursor: "pointer",
                  transition: "all 0.3s",
                  fontWeight: "bold",
                  boxShadow: `4px 4px 0 ${palette.accentDark}`,
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = "translate(-2px, -2px)";
                  e.currentTarget.style.boxShadow = `6px 6px 0 ${palette.accentDark}`;
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = "translate(0, 0)";
                  e.currentTarget.style.boxShadow = `4px 4px 0 ${palette.accentDark}`;
                }}
              >
                → Començar el diagnòstic
              </button>
            </div>
          </div>
        )}

        {/* PREGUNTES AMB ESQUEMA DE L'AULA */}
        {inQuestion && (
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "minmax(0, 1fr)",
              gap: "28px",
              animation: "slideUp 0.5s ease",
            }}
          >
            {/* Esquema de l'aula */}
            <div
              style={{
                background: palette.bgSoft,
                border: `1px solid ${palette.muted}44`,
                padding: "28px",
                boxShadow: "0 10px 40px rgba(0,0,0,0.4)",
                position: "relative",
              }}
            >
              {/* Pancarta inspirada en la imatge */}
              <div
                style={{
                  background: palette.panel,
                  color: palette.ink,
                  padding: "14px 20px",
                  marginBottom: "24px",
                  textAlign: "center",
                  fontFamily: "Georgia, serif",
                  fontWeight: "bold",
                  fontSize: "15px",
                  fontStyle: "italic",
                  boxShadow: "0 4px 12px rgba(0,0,0,0.3)",
                  position: "relative",
                  borderTop: `4px solid ${palette.wood}`,
                  borderBottom: `4px solid ${palette.wood}`,
                  maxWidth: "420px",
                  margin: "0 auto 24px",
                }}
              >
                Reunió de famílies · Inici de curs
                <div style={{ position: "absolute", top: "-18px", left: "20px", width: "2px", height: "18px", background: palette.wood }} />
                <div style={{ position: "absolute", top: "-18px", right: "20px", width: "2px", height: "18px", background: palette.wood }} />
              </div>

              {/* Escenari amb docent i ocells */}
              <div
                style={{
                  background: `linear-gradient(180deg, ${palette.curtain} 0%, ${palette.curtain}dd 100%)`,
                  padding: "14px",
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "flex-end",
                  gap: "24px",
                  borderBottom: `6px solid ${palette.wood}`,
                  minHeight: "70px",
                }}
              >
                <div style={{ textAlign: "center", fontSize: "32px", lineHeight: 1 }}>
                  <span role="img" aria-label="docent">👩‍🏫</span>
                </div>
                <div style={{ position: "relative", textAlign: "center" }}>
                  <div style={{ display: "flex", gap: "8px", fontSize: "30px", lineHeight: 1 }}>
                    <span role="img" aria-label="ocell 1">🦜</span>
                    <span role="img" aria-label="ocell 2">🕊️</span>
                  </div>
                  <div style={{ width: "90px", height: "5px", background: palette.wood, margin: "3px auto 0" }} />
                </div>
              </div>

              {/* Passadís */}
              <div
                style={{
                  height: "14px",
                  background: `linear-gradient(180deg, ${palette.wood} 0%, ${palette.wood}88 100%)`,
                  marginBottom: "24px",
                }}
              />

              {/* Comptador */}
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "16px",
                  fontFamily: "'Courier New', monospace",
                  fontSize: "11px",
                  letterSpacing: "2px",
                  color: palette.chalk,
                }}
              >
                <span>ASSISTENTS: {currentFilled}/{totalChairs}</span>
                <span style={{ color: palette.accent }}>
                  BUIDOR: {Math.round(((totalChairs - currentFilled) / totalChairs) * 100)}%
                </span>
              </div>

              {/* Graella de cadires */}
              <div
                style={{
                  display: "grid",
                  gridTemplateColumns: "repeat(5, 1fr)",
                  gap: "14px",
                  maxWidth: "460px",
                  margin: "0 auto",
                  padding: "16px",
                  background: `${palette.bg}66`,
                  border: `1px dashed ${palette.muted}44`,
                }}
              >
                {chairs.map((chair) => {
                  const isOccupied = occupiedChairs.has(chair.id);
                  const isSelected = selectedChair === chair.id;
                  return (
                    <button
                      key={chair.id}
                      onClick={() =>
                        !isOccupied && setSelectedChair(isSelected ? null : chair.id)
                      }
                      style={{
                        aspectRatio: "1",
                        background: "transparent",
                        border: "none",
                        padding: 0,
                        cursor: isOccupied ? "default" : "pointer",
                        position: "relative",
                        transition: "transform 0.3s ease",
                        transform: isSelected ? "scale(1.1)" : "scale(1)",
                      }}
                      onMouseEnter={(e) => {
                        if (!isOccupied) e.currentTarget.style.transform = "scale(1.08)";
                      }}
                      onMouseLeave={(e) => {
                        if (!isSelected && !isOccupied)
                          e.currentTarget.style.transform = "scale(1)";
                      }}
                    >
                      <ChairSVG
                        occupied={isOccupied}
                        highlighted={isSelected}
                        palette={palette}
                      />
                    </button>
                  );
                })}
              </div>

              {/* Missatge contextual */}
              <div
                style={{
                  marginTop: "18px",
                  textAlign: "center",
                  fontSize: "13px",
                  fontStyle: "italic",
                  minHeight: "44px",
                  padding: "0 12px",
                }}
              >
                {selectedChair !== null && !occupiedChairs.has(selectedChair) ? (
                  <span style={{ color: palette.accent }}>
                    Una cadira buida. Una família que no hi és.<br />
                    <span style={{ fontSize: "12px", color: palette.muted }}>
                      Respon el perquè per entendre per què no ha vingut.
                    </span>
                  </span>
                ) : (
                  <span style={{ color: palette.muted }}>
                    Cada perquè que contestes omple cadires.
                  </span>
                )}
              </div>

              {/* Barra de progrés */}
              <div
                style={{
                  height: "3px",
                  width: "100%",
                  background: `${palette.muted}33`,
                  marginTop: "16px",
                  position: "relative",
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${(step + 1) * 20}%`,
                    background: palette.accent,
                    transition: "width 0.8s ease",
                    boxShadow: `0 0 12px ${palette.accent}`,
                  }}
                />
              </div>
            </div>

            {/* Panell de preguntes */}
            <div
              style={{
                background: palette.panel,
                color: palette.ink,
                padding: "32px",
                position: "relative",
                boxShadow: "0 10px 40px rgba(0,0,0,0.3)",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "60px",
                  height: "60px",
                  borderTop: `3px solid ${palette.accent}`,
                  borderLeft: `3px solid ${palette.accent}`,
                }}
              />
              <div
                style={{
                  position: "absolute",
                  bottom: 0,
                  right: 0,
                  width: "60px",
                  height: "60px",
                  borderBottom: `3px solid ${palette.accent}`,
                  borderRight: `3px solid ${palette.accent}`,
                }}
              />

              {answers.length > 0 && (
                <div
                  style={{
                    marginBottom: "28px",
                    paddingBottom: "24px",
                    borderBottom: `1px dashed ${palette.inkSoft}66`,
                  }}
                >
                  <div
                    style={{
                      fontSize: "10px",
                      letterSpacing: "3px",
                      color: palette.inkSoft,
                      marginBottom: "14px",
                      fontFamily: "'Courier New', monospace",
                    }}
                  >
                    CADENA CAUSAL FINS ARA
                  </div>
                  {answers.map((ans, i) => (
                    <div
                      key={i}
                      style={{
                        fontSize: "14px",
                        marginBottom: "10px",
                        color: palette.inkSoft,
                        paddingLeft: `${i * 18}px`,
                        animation: "fadeIn 0.5s ease",
                        lineHeight: 1.4,
                      }}
                    >
                      <span
                        style={{
                          color: palette.accent,
                          fontFamily: "'Courier New', monospace",
                          fontSize: "11px",
                          marginRight: "8px",
                          fontWeight: "bold",
                        }}
                      >
                        #{i + 1}
                      </span>
                      <span style={{ fontStyle: "italic" }}>"{ans}"</span>
                    </div>
                  ))}
                </div>
              )}

              <div
                style={{
                  fontSize: "10px",
                  letterSpacing: "4px",
                  color: palette.accent,
                  fontFamily: "'Courier New', monospace",
                  marginBottom: "12px",
                  fontWeight: "bold",
                }}
              >
                PERQUÈ {step + 1} / 5
              </div>

              <div
                style={{
                  fontSize: "clamp(20px, 3vw, 28px)",
                  fontStyle: "italic",
                  marginBottom: "24px",
                  lineHeight: 1.3,
                  color: palette.ink,
                }}
              >
                {questions[step]}
              </div>

              <textarea
                value={currentAnswer}
                onChange={(e) => setCurrentAnswer(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    handleSubmit();
                  }
                }}
                placeholder="Escriu la teva resposta aquí..."
                style={{
                  width: "100%",
                  minHeight: "80px",
                  background: "#ffffff",
                  border: `1px solid ${palette.inkSoft}66`,
                  color: palette.ink,
                  padding: "14px",
                  fontSize: "15px",
                  fontFamily: "Georgia, serif",
                  resize: "vertical",
                  outline: "none",
                  boxSizing: "border-box",
                }}
                onFocus={(e) => (e.target.style.borderColor = palette.accent)}
                onBlur={(e) => (e.target.style.borderColor = `${palette.inkSoft}66`)}
              />

              <div style={{ marginTop: "16px" }}>
                <div
                  style={{
                    fontSize: "10px",
                    letterSpacing: "2px",
                    color: palette.inkSoft,
                    marginBottom: "10px",
                    fontFamily: "'Courier New', monospace",
                  }}
                >
                  ↳ O TRIA UNA HIPÒTESI:
                </div>
                <div style={{ display: "flex", flexWrap: "wrap", gap: "8px" }}>
                  {suggestions[step].map((s, i) => (
                    <button
                      key={i}
                      onClick={() => handleSuggestion(s)}
                      style={{
                        background: "transparent",
                        border: `1px solid ${palette.inkSoft}88`,
                        color: palette.inkSoft,
                        padding: "8px 12px",
                        fontSize: "12px",
                        fontFamily: "Georgia, serif",
                        fontStyle: "italic",
                        cursor: "pointer",
                        transition: "all 0.2s",
                      }}
                      onMouseEnter={(e) => {
                        e.currentTarget.style.background = palette.ink;
                        e.currentTarget.style.color = palette.panel;
                        e.currentTarget.style.borderColor = palette.ink;
                      }}
                      onMouseLeave={(e) => {
                        e.currentTarget.style.background = "transparent";
                        e.currentTarget.style.color = palette.inkSoft;
                        e.currentTarget.style.borderColor = `${palette.inkSoft}88`;
                      }}
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>

              <button
                onClick={handleSubmit}
                disabled={!currentAnswer.trim()}
                style={{
                  marginTop: "24px",
                  background: currentAnswer.trim() ? palette.accent : `${palette.inkSoft}33`,
                  color: currentAnswer.trim() ? palette.panel : palette.inkSoft,
                  border: "none",
                  padding: "14px 28px",
                  fontSize: "12px",
                  fontFamily: "'Courier New', monospace",
                  letterSpacing: "3px",
                  textTransform: "uppercase",
                  cursor: currentAnswer.trim() ? "pointer" : "not-allowed",
                  transition: "all 0.2s",
                  fontWeight: "bold",
                  boxShadow: currentAnswer.trim() ? `3px 3px 0 ${palette.accentDark}` : "none",
                }}
              >
                {step === 4 ? "→ Revelar la causa arrel" : "→ Següent perquè"}
              </button>
            </div>
          </div>
        )}

        {/* FINAL AMB FOTO IL·LUMINADA */}
        {showFinal && (
          <div style={{ animation: "fadeIn 0.8s ease" }}>
            <div
              style={{
                position: "relative",
                marginBottom: "32px",
                border: `1px solid ${palette.muted}44`,
                overflow: "hidden",
                boxShadow: "0 20px 60px rgba(0,0,0,0.5)",
              }}
            >
              <img
                src={IMAGE_DATA}
                alt=""
                style={{
                  width: "100%",
                  display: "block",
                  maxHeight: "320px",
                  objectFit: "cover",
                  objectPosition: "center 55%",
                  filter: "contrast(1.1) saturate(1.2) brightness(1.1)",
                }}
              />
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  background:
                    "radial-gradient(ellipse at center, rgba(255, 220, 150, 0.2) 0%, transparent 70%)",
                  pointerEvents: "none",
                }}
              />
              <div
                style={{
                  position: "absolute",
                  top: "14px",
                  left: "14px",
                  background: "rgba(43, 93, 43, 0.92)",
                  padding: "10px 16px",
                  fontFamily: "'Courier New', monospace",
                  fontSize: "11px",
                  letterSpacing: "3px",
                  color: palette.panel,
                  fontWeight: "bold",
                }}
              >
                ✓ DIAGNÒSTIC COMPLET · AULA PLENA
              </div>
            </div>

            <div
              style={{
                background: palette.panel,
                color: palette.ink,
                padding: "36px",
                boxShadow: "0 10px 40px rgba(0,0,0,0.3)",
                position: "relative",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "80px",
                  height: "80px",
                  borderTop: `4px solid ${palette.accent}`,
                  borderLeft: `4px solid ${palette.accent}`,
                }}
              />

              <div
                style={{
                  fontSize: "10px",
                  letterSpacing: "4px",
                  color: palette.accent,
                  fontFamily: "'Courier New', monospace",
                  marginBottom: "8px",
                  fontWeight: "bold",
                }}
              >
                CAUSA ARREL IDENTIFICADA
              </div>
              <h2
                style={{
                  fontSize: "clamp(22px, 3.5vw, 32px)",
                  fontStyle: "italic",
                  margin: "0 0 28px",
                  lineHeight: 1.3,
                  color: palette.ink,
                  fontWeight: 400,
                }}
              >
                "{answers[4]}"
              </h2>

              <div
                style={{
                  padding: "20px",
                  background: "#ffffff",
                  borderLeft: `4px solid ${palette.accent}`,
                  marginBottom: "28px",
                }}
              >
                <div
                  style={{
                    fontSize: "11px",
                    letterSpacing: "3px",
                    color: palette.inkSoft,
                    marginBottom: "14px",
                    fontFamily: "'Courier New', monospace",
                  }}
                >
                  TRAÇABILITAT DEL RAONAMENT
                </div>
                <div
                  style={{
                    fontSize: "14px",
                    fontWeight: "bold",
                    color: palette.accent,
                    marginBottom: "12px",
                    fontStyle: "italic",
                  }}
                >
                  {questions[0]}
                </div>
                {answers.map((ans, i) => (
                  <div
                    key={i}
                    style={{
                      fontSize: "13px",
                      marginBottom: "8px",
                      color: palette.inkSoft,
                      paddingLeft: `${(i + 1) * 16}px`,
                      fontStyle: "italic",
                      lineHeight: 1.4,
                    }}
                  >
                    <span style={{ color: palette.accent, fontWeight: "bold" }}>↳</span> "{ans}"
                  </div>
                ))}
              </div>

              <div
                style={{
                  fontSize: "14px",
                  color: palette.ink,
                  lineHeight: 1.6,
                  padding: "20px",
                  background: `${palette.accent}11`,
                  borderTop: `2px solid ${palette.accent}`,
                  marginBottom: "28px",
                }}
              >
                <strong style={{ color: palette.accent }}>Reflexió per a l'equip directiu:</strong>{" "}
                si aquesta és la causa arrel, les solucions han d'atacar-la
                directament. No n'hi ha prou amb canviar l'horari de la reunió si
                el problema real és una altra cosa. La sala només s'omplirà quan
                l'arrel estigui resolta.
              </div>

              <div style={{ textAlign: "center" }}>
                <button
                  onClick={reset}
                  style={{
                    background: "transparent",
                    border: `2px solid ${palette.ink}`,
                    color: palette.ink,
                    padding: "14px 32px",
                    fontSize: "12px",
                    fontFamily: "'Courier New', monospace",
                    letterSpacing: "3px",
                    textTransform: "uppercase",
                    cursor: "pointer",
                    transition: "all 0.2s",
                    fontWeight: "bold",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = palette.ink;
                    e.currentTarget.style.color = palette.panel;
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = "transparent";
                    e.currentTarget.style.color = palette.ink;
                  }}
                >
                  ↻ Començar un nou diagnòstic
                </button>
              </div>
            </div>
          </div>
        )}

        <div
          style={{
            textAlign: "center",
            marginTop: "48px",
            fontSize: "10px",
            color: palette.muted,
            letterSpacing: "3px",
            fontFamily: "'Courier New', monospace",
          }}
        >
          — MÈTODE DE SAKICHI TOYODA · ADAPTACIÓ PER A CENTRES EDUCATIUS —
        </div>
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(8px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes slideUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes sitDown {
          from { opacity: 0; transform: translateY(-10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}

function ChairSVG({ occupied, highlighted, palette }) {
  return (
    <svg viewBox="0 0 60 70" style={{ width: "100%", height: "100%" }}>
      {occupied && (
        <g style={{ animation: "sitDown 0.5s ease" }}>
          <circle cx="30" cy="18" r="7" fill={palette.wood} />
          <path
            d="M 18 38 Q 18 28 30 28 Q 42 28 42 38 L 42 48 L 18 48 Z"
            fill={palette.accent}
          />
          <rect x="14" y="32" width="5" height="16" rx="2" fill={palette.accent} />
          <rect x="41" y="32" width="5" height="16" rx="2" fill={palette.accent} />
        </g>
      )}
      <rect
        x="14"
        y={occupied ? "8" : "14"}
        width="32"
        height={occupied ? "42" : "36"}
        rx="2"
        fill="none"
        stroke={highlighted ? palette.accent : palette.muted}
        strokeWidth={highlighted ? "3" : "2"}
      />
      <rect
        x="10"
        y="48"
        width="40"
        height="6"
        rx="1"
        fill={highlighted ? palette.accent : palette.wood}
      />
      <rect x="12" y="54" width="3" height="14" fill={palette.wood} />
      <rect x="45" y="54" width="3" height="14" fill={palette.wood} />
      <rect x="20" y="54" width="2" height="12" fill={palette.muted} opacity="0.5" />
      <rect x="38" y="54" width="2" height="12" fill={palette.muted} opacity="0.5" />
      {!occupied && (
        <text
          x="30"
          y="32"
          textAnchor="middle"
          fontSize="16"
          fill={highlighted ? palette.accent : `${palette.muted}88`}
          fontFamily="Georgia, serif"
          fontStyle="italic"
          fontWeight="bold"
        >
          ?
        </text>
      )}
    </svg>
  );
}
